SET @dm_idem_sql=IF((SELECT COUNT(*) FROM information_schema.columns WHERE table_schema=DATABASE() AND table_name='messages' AND column_name='idempotencyKey')=0,'ALTER TABLE `messages` ADD COLUMN `idempotencyKey` varchar(64) NULL, ADD COLUMN `requestFingerprint` varchar(64) NULL, ADD UNIQUE INDEX `messages_sender_idempotency_unique` (`senderId`,`idempotencyKey`)','SELECT 1');
PREPARE dm_idem_stmt FROM @dm_idem_sql;EXECUTE dm_idem_stmt;DEALLOCATE PREPARE dm_idem_stmt;
CREATE TABLE IF NOT EXISTS `directMessageQuotaWindows` (`id` int AUTO_INCREMENT PRIMARY KEY,`senderId` int NOT NULL,`windowStart` timestamp NOT NULL,`sendCount` int NOT NULL DEFAULT 0,`createdAt` timestamp NOT NULL DEFAULT CURRENT_TIMESTAMP,`updatedAt` timestamp NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,UNIQUE INDEX `dm_quota_sender_window_unique` (`senderId`,`windowStart`),CONSTRAINT `dm_quota_sender_fk` FOREIGN KEY (`senderId`) REFERENCES `users` (`id`) ON DELETE CASCADE);
CREATE TABLE IF NOT EXISTS `directMessageNotificationOutbox` (`id` int AUTO_INCREMENT PRIMARY KEY,`messageId` int NOT NULL,`recipientId` int NOT NULL,`status` enum('pending','leased','sent','failed','unknown') NOT NULL DEFAULT 'pending',`attemptCount` int NOT NULL DEFAULT 0,`nextAttemptAt` timestamp NULL,`createdAt` timestamp NOT NULL DEFAULT CURRENT_TIMESTAMP,UNIQUE INDEX `dm_notification_outbox_message_unique` (`messageId`),INDEX `dm_notification_outbox_claim_idx` (`status`,`nextAttemptAt`),CONSTRAINT `dm_outbox_message_fk` FOREIGN KEY (`messageId`) REFERENCES `messages` (`id`) ON DELETE CASCADE,CONSTRAINT `dm_outbox_recipient_fk` FOREIGN KEY (`recipientId`) REFERENCES `users` (`id`) ON DELETE CASCADE);
